import itertools, json
people = set('KLMNPQR')
west = set('KPR')
Aopts = ['KMP','LNP','KLN','MQR','LMQ']
Bopts = ['LPQ','NPR','LMP','MNR','KNP']
Adays = [{2,7},{1,6,7},{7},{8},{2,7}]
Bdays = [{4,6},{3},{2,8},{3},{6,7,8}]
As = [a for a in itertools.product(*Aopts) if len(set(a)) == 5]
Bs = [b for b in itertools.product(*Bopts) if len(set(b)) == 5]
counts = {}
witnesses = {}
total = 0
for a in As:
    for b in Bs:
        shared = set(a) & set(b)
        if len(shared) != 3 or len(shared & west) != 1:
            continue
        days = {p:set() for p in people}
        for assignment, rows in [(a,Adays),(b,Bdays)]:
            for p, ds in zip(assignment,rows):
                days[p].update(ds)
        n = sum(len(ds)>=3 for ds in days.values())
        total += 1
        counts[n] = counts.get(n,0)+1
        witnesses.setdefault(n, {'A': ''.join(a), 'B': ''.join(b)})
lo, hi = min(counts), max(counts)
result = {'feasible_linkages':total,'bounds':[lo,hi],'low_witness':witnesses[lo],'high_witness':witnesses[hi],'decision':'confirmed' if lo>=4 else 'excluded' if hi<4 else 'undetermined'}
payload=json.dumps(result)
recovered=json.loads(payload)
assert recovered['feasible_linkages'] == sum(counts.values())
for field, expected in [('low_witness',lo),('high_witness',hi)]:
    w = recovered[field]
    assert set(w)=={'A','B'}
    ds={p:set() for p in people}
    for key,opts,rows in [('A',Aopts,Adays),('B',Bopts,Bdays)]:
        s=w[key]
        assert len(s)==5 and len(set(s))==5
        for p,o,d in zip(s,opts,rows):
            assert p in o
            ds[p] |= d
    intersection=set(w['A']) & set(w['B'])
    assert len(intersection)==3 and len(intersection & west)==1
    assert sum(len(d)>=3 for d in ds.values())==expected
print(payload)
print('histogram',counts)
print('witness day counts', {field: {p:len(set().union(*[d for key,rows in [('A',Adays),('B',Bdays)] for q,d in zip(recovered[field][key],rows) if q==p])) for p in sorted(people)} for field in ['low_witness','high_witness']})

