import itertools,json
opts={'A':['KMP','LNP','KLN','MQR','LMQ'],'B':['LPQ','NPR','LMP','MNR','KNP']}
rows={'A':[{2,7},{1,6,7},{7},{8},{2,7}],'B':[{4,6},{3},{2,8},{3},{6,7,8}]}
people=set('KLMNPQR'); west=set('KPR')
assignments={k:[x for x in itertools.product(*v) if len(set(x))==5] for k,v in opts.items()}
old=[]; feasible=[]
def score(w):
    days={p:set() for p in people}
    for k in ['A','B']:
        for p,ds in zip(w[k],rows[k]): days[p].update(ds)
    return sum(len(ds)>=3 for ds in days.values())
for a in assignments['A']:
    for b in assignments['B']:
        shared=set(a)&set(b)
        if len(shared)!=3 or len(shared&west)!=1: continue
        w={'A':''.join(a),'B':''.join(b)}
        old.append(w)
        if a[0]=='M' and a[1]==b[3]: feasible.append((score(w),w))
lo=min(n for n,w in feasible); hi=max(n for n,w in feasible)
result={'feasible_linkages':len(feasible),'bounds':[lo,hi],'low_witness':next(w for n,w in feasible if n==lo),'high_witness':next(w for n,w in feasible if n==hi),'decision':'confirmed' if lo>=4 else 'excluded' if hi<4 else 'undetermined'}
payload=json.dumps(result)
r=json.loads(payload)
assert set(r)=={'feasible_linkages','bounds','low_witness','high_witness','decision'}
assert len(old)==589 and len(feasible)<len(old)
for field,n in [('low_witness',lo),('high_witness',hi)]:
    w=r[field]
    assert set(w)=={'A','B'}
    for k in ['A','B']:
        assert len(w[k])==5 and len(set(w[k]))==5
        assert all(p in allowed for p,allowed in zip(w[k],opts[k]))
    shared=set(w['A'])&set(w['B'])
    assert len(shared)==3 and len(shared&west)==1
    assert w['A'][0]=='M' and w['A'][1]==w['B'][3]
    assert score(w)==n
assert any(w['A'][0]!='M' or w['A'][1]!=w['B'][3] for w in old)
print(payload)
print('histogram', {n:sum(s==n for s,w in feasible) for n in sorted(set(s for s,w in feasible))})

